_LLM_TOKEN_QA_RE = re.compile(
    r"(?:^|[^a-z0-9])llm[_\s-]*token[_\s-]*issue",
    re.IGNORECASE,
)
_MISSING_IMAGE_QA_RE = re.compile(
    r"(?:^|[^a-z0-9])missing[_\s-]*images?(?=$|[^a-z0-9])",
    re.IGNORECASE,
)


def _sync_parent_chunk_qa_summary(prog, parent_key, chunk_key):
    """Mirror aggregate child QA state without failing the parent chapter."""
    if not isinstance(prog, dict):
        return None
    chunk_entry = prog.get("chapter_chunks", {}).get(str(chunk_key or ""))
    parent = prog.get("chapters", {}).get(parent_key)
    if not isinstance(chunk_entry, dict) or not isinstance(parent, dict):
        return None
    ensure_chunk_entry_schema(chunk_entry)
    summary = chunk_failure_summary(chunk_entry)
    failed_indices = sorted(
        int(index)
        for index, record in chunk_entry.get("entries", {}).items()
        if isinstance(record, dict)
        and str(record.get("status") or "").lower() in {"qa_failed", "failed"}
    )
    parent["chunk_qa_summary"] = {
        **summary,
        "failed_indices": failed_indices,
        "last_updated": time.time(),
    }
    parent["has_chunk_qa_failures"] = bool(failed_indices)
    parent["chunk_qa_issues_found"] = {
        index: list(record.get("qa_issues_found") or [])
        for index, record in chunk_entry.get("entries", {}).items()
        if isinstance(record, dict) and record.get("qa_issues_found")
    }
    if not failed_indices:
        parent.pop("chunk_qa_issues_found", None)
    return summary


class _KeepOpenActionMenu(QMenu):
    """QMenu that leaves explicitly persistent actions open after activation."""

    KEEP_OPEN_PROPERTY = "sdl_keep_menu_open"

    @classmethod
    def _keeps_open(cls, action):
        return bool(
            action is not None
            and action.isEnabled()
            and action.property(cls.KEEP_OPEN_PROPERTY)
        )

    def mouseReleaseEvent(self, event):
        try:
            position = event.position().toPoint()
        except AttributeError:
            position = event.pos()
        action = self.actionAt(position)
        if self._keeps_open(action):
            self.setActiveAction(action)
            action.trigger()
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def keyPressEvent(self, event):
        if (
            event.key() in {Qt.Key_Return, Qt.Key_Enter, Qt.Key_Space}
            and self._keeps_open(self.activeAction())
        ):
            self.activeAction().trigger()
            event.accept()
            return
        super().keyPressEvent(event)


def _is_progress_sidecar_entry(entry=None, output_file=None):
    """Return whether a progress row points at an internal workspace sidecar."""
    entry = entry if isinstance(entry, dict) else {}
    candidates = (
        output_file,
        entry.get("output_file"),
        entry.get("original_basename"),
        entry.get("filename"),
    )
    return any(
        os.path.basename(str(candidate or "")).casefold()
        in _PROGRESS_SIDECAR_FILENAMES
        for candidate in candidates
        if candidate
    )


def _progress_entry_has_raw_foreign_text_qa(entry):
    """Return whether a progress entry carries a raw foreign-text QA issue."""
    seen = set()
    current = entry
    while isinstance(current, dict) and id(current) not in seen:
        seen.add(id(current))
        values = []
        for key in (
            'qa_issues_found', 'qa_issues', 'failure_reason', 'error_message'
        ):
            value = current.get(key)
            if isinstance(value, dict):
                values.extend(value.keys())
                values.extend(value.values())
            elif isinstance(value, (list, tuple, set)):
                values.extend(value)
            elif value is not None:
                values.append(value)
        for value in values:
            text = str(value or '').strip()
            normalized = text.lower().replace('-', '_').replace(' ', '_')
            if (
                _RAW_FOREIGN_TEXT_QA_RE.search(normalized)
                or ('_text_found_' in normalized and '_chars_' in normalized)
            ):
                return True
        current = current.get('previous_progress_entry')
    return False


def _qa_value_has_llm_token_issue(value):
    """Return whether a progress QA value identifies an LLM-token issue."""
    if isinstance(value, dict):
        return any(
            _qa_value_has_llm_token_issue(key)
            or _qa_value_has_llm_token_issue(item)
            for key, item in value.items()
        )
    if isinstance(value, (list, tuple, set)):
        return any(_qa_value_has_llm_token_issue(item) for item in value)
    return bool(_LLM_TOKEN_QA_RE.search(str(value or "")))


def _progress_entry_has_llm_token_qa(entry):
    """Return whether an entry or its restorable snapshot has LLM-token QA."""
    seen = set()
    current = entry
    while isinstance(current, dict) and id(current) not in seen:
        seen.add(id(current))
        for key in (
            'qa_issues_found', 'qa_issues', 'qa_issue_previews',
            'failure_reason', 'error_message',
        ):
            if _qa_value_has_llm_token_issue(current.get(key)):
                return True
        current = current.get('previous_progress_entry')
    return False


def _without_llm_token_qa(value):
    """Remove only LLM-token issue values while preserving other QA details."""
    if isinstance(value, list):
        filtered = []
        for item in value:
            cleaned = _without_llm_token_qa(item)
            if cleaned not in (None, "", [], (), {}, set()):
                filtered.append(cleaned)
        return filtered
    if isinstance(value, tuple):
        return tuple(_without_llm_token_qa(list(value)))
    if isinstance(value, set):
        return set(_without_llm_token_qa(list(value)))
    if isinstance(value, dict):
        filtered = {}
        for key, item in value.items():
            if _qa_value_has_llm_token_issue(key):
                continue
            cleaned = _without_llm_token_qa(item)
            if cleaned not in (None, "", [], (), {}, set()):
                filtered[key] = cleaned
        return filtered
    if _qa_value_has_llm_token_issue(value):
        return None
    return value


def _clear_llm_token_qa_markers(entry):
    """Clear resolved LLM-token QA markers and return ``(changed, remaining)``."""
    if not isinstance(entry, dict):
        return False, False

    changed = False
    for key in (
        'qa_issues_found', 'qa_issue_previews', 'failure_reason',
        'error_message', 'qa_issues',
    ):
        if key not in entry:
            continue
        original = entry.get(key)
        filtered = _without_llm_token_qa(original)
        if filtered != original:
            changed = True
        if filtered in (None, "", [], (), {}, set()):
            entry.pop(key, None)
        else:
            entry[key] = filtered

    previous = entry.get('previous_progress_entry')
    previous_remaining = False
    if isinstance(previous, dict):
        previous_changed, previous_remaining = _clear_llm_token_qa_markers(
            previous
        )
        changed = changed or previous_changed

    remaining = previous_remaining or any(
        bool(entry.get(key))
        for key in (
            'qa_issues_found', 'qa_issue_previews', 'failure_reason',
            'error_message',
        )
    )
    qa_flag = entry.get('qa_issues')
    if not isinstance(qa_flag, bool):
        remaining = remaining or bool(qa_flag)

    if not remaining:
        if entry.pop('qa_issues', None) is not None:
            changed = True
        if entry.pop('qa_timestamp', None) is not None:
            changed = True
        if str(entry.get('status') or '').lower() in {'qa_failed', 'failed'}:
            entry['status'] = 'completed'
            entry['last_updated'] = time.time()
            changed = True
    return changed, remaining


def _qa_value_has_missing_image_issue(value):
    """Return whether a structured QA value identifies missing images."""
    if isinstance(value, dict):
        return any(
            _qa_value_has_missing_image_issue(key)
            or _qa_value_has_missing_image_issue(item)
            for key, item in value.items()
        )
    if isinstance(value, (list, tuple, set)):
        return any(_qa_value_has_missing_image_issue(item) for item in value)
    return bool(_MISSING_IMAGE_QA_RE.search(str(value or "")))


def _progress_entry_has_missing_image_qa(entry):
    """Return whether an entry or restorable snapshot has missing-image QA."""
    seen = set()
    current = entry
    while isinstance(current, dict) and id(current) not in seen:
        seen.add(id(current))
        for key in (
            'qa_issues_found', 'qa_issues', 'qa_issue_previews',
            'failure_reason', 'error_message',
        ):
            if _qa_value_has_missing_image_issue(current.get(key)):
                return True
        current = current.get('previous_progress_entry')
    return False


def _qa_scalar_is_missing_image_issue(value):
    """Return whether one scalar starts with a missing-image issue marker."""
    if isinstance(value, (dict, list, tuple, set)):
        return False
    return bool(_MISSING_IMAGE_QA_RE.match(str(value or "").strip()))


def _qa_mapping_is_missing_image_issue(value):
    """Identify a structured issue by its code/type fields, not its preview."""
    if not isinstance(value, dict):
        return False
    identity_keys = {'type', 'issue', 'issue_type', 'code', 'name'}
    return any(
        str(key).strip().lower() in identity_keys
        and _qa_scalar_is_missing_image_issue(item)
        for key, item in value.items()
    )


def _without_missing_image_qa(value):
    """Remove complete missing-image issue values while preserving others."""
    if isinstance(value, list):
        filtered = []
        for item in value:
            if (
                _qa_scalar_is_missing_image_issue(item)
                or _qa_mapping_is_missing_image_issue(item)
            ):
                continue
            cleaned = (
                _without_missing_image_qa(item)
                if isinstance(item, (dict, list, tuple, set))
                else item
            )
            if cleaned not in (None, "", [], (), {}, set()):
                filtered.append(cleaned)
        return filtered
    if isinstance(value, tuple):
        return tuple(_without_missing_image_qa(list(value)))
    if isinstance(value, set):
        return set(_without_missing_image_qa(list(value)))
    if isinstance(value, dict):
        if _qa_mapping_is_missing_image_issue(value):
            return None
        filtered = {}
        for key, item in value.items():
            if _qa_scalar_is_missing_image_issue(key):
                continue
            cleaned = (
                _without_missing_image_qa(item)
                if isinstance(item, (dict, list, tuple, set))
                else item
            )
            if cleaned not in (None, "", [], (), {}, set()):
                filtered[key] = cleaned
        return filtered
    if _qa_scalar_is_missing_image_issue(value):
        return None
    return value


def _clear_missing_image_qa_markers(entry):
    """Clear only missing-image QA markers; return ``(changed, remaining)``."""
    if not isinstance(entry, dict):
        return False, False

    changed = False
    for key in ('qa_issues_found', 'qa_issue_previews', 'qa_issues'):
        if key not in entry:
            continue
        original = entry.get(key)
        filtered = _without_missing_image_qa(original)
        if filtered != original:
            changed = True
        if filtered in (None, "", [], (), {}, set()):
            entry.pop(key, None)
        else:
            entry[key] = filtered

    # Error fields can represent independent translation failures. Never
    # remove them merely because a missing-image marker was also present.
    previous = entry.get('previous_progress_entry')
    previous_remaining = False
    if isinstance(previous, dict):
        previous_changed, previous_remaining = _clear_missing_image_qa_markers(
            previous
        )
        changed = changed or previous_changed

    remaining = previous_remaining or any(
        bool(entry.get(key))
        for key in (
            'qa_issues_found', 'qa_issue_previews', 'failure_reason',
            'error_message',
        )
    )
    qa_flag = entry.get('qa_issues')
    if not isinstance(qa_flag, bool):
        remaining = remaining or bool(qa_flag)

    if not remaining:
        if entry.pop('qa_issues', None) is not None:
            changed = True
        if entry.pop('qa_timestamp', None) is not None:
            changed = True
        if str(entry.get('status') or '').lower() in {'qa_failed', 'failed'}:
            entry['status'] = 'completed'
            entry['last_updated'] = time.time()
            changed = True
    return changed, remaining


def _repair_empty_attribute_qa_file(file_path):
    """Apply the shared empty-attribute fixer and verify the issue is gone."""
    from _empty_attr_fix import count_empty_attr_tags, fix_empty_attr_tags

    raw_path = str(file_path or "").strip()
    path = (
        os.path.abspath(os.path.normpath(raw_path))
        if raw_path else ""
    )
    if not path or not os.path.isfile(path):
        return {
            'resolved': False,
            'changed': False,
            'repaired': 0,
            'remaining': 0,
            'repairs': [],
            'error': f"Output file not found: {path or file_path}",
        }
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as handle:
            original = handle.read()
        before = count_empty_attr_tags(original)
        if before == 0:
            return {
                'resolved': True,
                'changed': False,
                'repaired': 0,
                'remaining': 0,
                'repairs': [],
                'error': '',
            }

        repairs = []
        repaired_content = fix_empty_attr_tags(
            original,
            repair_log=repairs,
            repair_log_limit=20,
        )
        remaining = count_empty_attr_tags(repaired_content)
        if remaining:
            return {
                'resolved': False,
                'changed': False,
                'repaired': before - remaining,
                'remaining': remaining,
                'repairs': repairs,
                'error': (
                    f"{remaining} empty-attribute tag(s) remain after repair."
                ),
            }

        temporary = (
            f"{path}.{os.getpid()}.{threading.get_ident()}.llm-token-fix.tmp"
        )
        try:
            with open(temporary, 'w', encoding='utf-8', newline='') as handle:
                handle.write(repaired_content)
            os.replace(temporary, path)
        finally:
            if os.path.isfile(temporary):
                try:
                    os.remove(temporary)
                except OSError:
                    pass
        return {
            'resolved': True,
            'changed': repaired_content != original,
            'repaired': before,
            'remaining': 0,
            'repairs': repairs,
            'error': '',
        }
    except Exception as exc:
        return {
            'resolved': False,
            'changed': False,
            'repaired': 0,
            'remaining': 0,
            'repairs': [],
            'error': str(exc),
        }

# --- Non-blocking access to TransateKRtoEN.ProgressManager ------------------
# TransateKRtoEN is a very heavy import chain (tiktoken, ebooklib, bs4,
# unified_api_client, GlossaryManager, ...). In frozen (PyInstaller onefile)
# builds the first import can take 10-20s. When the translation worker thread
# starts that import, any plain `from TransateKRtoEN import ProgressManager`
# executed on the GUI thread (e.g. by this dialog's 2s auto-refresh timer)
# blocks on Python's per-module import lock until the worker finishes —
# freezing the entire GUI for the whole import. These helpers only ever do a
# lock-free sys.modules/getattr lookup on the GUI thread and, if the module
# isn't ready yet, warm it once in a background thread instead of blocking.
_TRANSLATE_MODULE_WARMUP_STARTED = threading.Event()
_EPUB_LIBRARY_WARMUP_STARTED = threading.Event()
_EPUB_READER_ENGINE_PREWARM_SCHEDULED = False


def _warm_translate_module_in_background():
    """Kick off the heavy TransateKRtoEN import on a daemon thread (once)."""
    if _TRANSLATE_MODULE_WARMUP_STARTED.is_set():
        return
    _TRANSLATE_MODULE_WARMUP_STARTED.set()

    def _warm():
        try:
            import TransateKRtoEN  # noqa: F401
        except Exception:
            pass

    threading.Thread(target=_warm, name="translate-module-warmup", daemon=True).start()


def _get_progress_manager_nonblocking():
    """Return TransateKRtoEN.ProgressManager without touching the import lock.

    Returns None when TransateKRtoEN is not fully imported yet (e.g. it is
    being imported right now by the translation worker in a frozen build).
    Callers on the GUI thread should treat None as "skip this tick" rather
    than importing the module themselves.
    """
    mod = sys.modules.get('TransateKRtoEN')
    if mod is not None:
        pm = getattr(mod, 'ProgressManager', None)
        if pm is not None:
            return pm
    _warm_translate_module_in_background()
    return None


def _warm_epub_library_in_background():
    """Warm the reader's lazy module before a Progress Manager menu click.

    Frozen builds can spend seconds unpacking/importing QtWebEngine on the
    first ``epub_library`` import. Progress Manager already exists by the time
    this helper runs, so importing on a daemon thread hides that one-time cost
    behind the user's normal interaction with the dialog.
    """
    if 'epub_library' in sys.modules or _EPUB_LIBRARY_WARMUP_STARTED.is_set():
        return
    _EPUB_LIBRARY_WARMUP_STARTED.set()

    def _warm():
        try:
            import epub_library  # noqa: F401
        except Exception:
            pass

    threading.Thread(
        target=_warm,
        name="epub-reader-module-warmup",
        daemon=True,
    ).start()


def _schedule_epub_reader_engine_prewarm():
    """Create the hidden Chromium warmup view once the lazy import finishes."""
    global _EPUB_READER_ENGINE_PREWARM_SCHEDULED
    if _EPUB_READER_ENGINE_PREWARM_SCHEDULED:
        return
    _EPUB_READER_ENGINE_PREWARM_SCHEDULED = True
    _warm_epub_library_in_background()

    def _try_prewarm(attempt=0):
        module = sys.modules.get('epub_library')
        prewarm = getattr(module, 'prewarm_epub_reader_webengine', None)
        if callable(prewarm):
            try:
                prewarm()
            except Exception:
                pass
            return
        # A frozen-build import can take several seconds. Poll without ever
        # touching its import lock from the GUI thread.
        if attempt < 200:
            QTimer.singleShot(
                50,
                lambda: _try_prewarm(attempt + 1),
            )

    # Let the Progress Manager shell and first list batch paint before the
    # one-time Chromium startup runs on the GUI thread.
    QTimer.singleShot(250, _try_prewarm)
