@lru_cache(maxsize=32768)
def _normalize_progress_match_text(name):
    """Cached string-only implementation for stable chapter filenames."""
    base = os.path.basename(name)
    if base.startswith("response_"):
        base = base[len("response_"):]
    # This is the hot path for every OPF/progress comparison.  Once basename
    # has removed the directory, rfind preserves splitext's dotfile behavior
    # without repeatedly invoking the much heavier path parser.
    while (dot_index := base.rfind(".")) > 0:
        base = base[:dot_index]
    return base


def _normalize_progress_match_name(name):
    """Normalize source/output names used by Progress Manager matching."""
    if not name:
        return ""
    return _normalize_progress_match_text(str(name))


def _progress_entry_has_meaningful_tts_state(entry):
    """Return whether a non-audio progress entry still needs TTS reconciliation."""
    if not isinstance(entry, dict):
        return False
    if entry.get('tts_file'):
        return True
    tts_status = str(entry.get('tts_status') or '').lower().strip()
    return tts_status not in ('', 'none', 'no_tts')


def _sdlxliff_logical_output_key(path_or_name):
    """Return one identity for retained- and response-named sidecars."""
    name = os.path.basename(str(path_or_name or "").replace("\\", "/"))
    if name.casefold().endswith(".sdlxliff"):
        name = name[:-len(".sdlxliff")]
    return _normalize_progress_match_name(name).casefold()


def _existing_sdlxliff_sidecars_by_logical_output(output_dir):
    """Index sidecars without treating a filename-mode change as new work."""
    sidecar_dir = os.path.join(str(output_dir or ""), "SDLXLIFF")
    indexed = {}
    try:
        with os.scandir(sidecar_dir) as entries:
            for entry in entries:
                if not entry.is_file() or not entry.name.casefold().endswith(".sdlxliff"):
                    continue
                logical_key = _sdlxliff_logical_output_key(entry.name)
                if logical_key:
                    indexed.setdefault(logical_key, entry.path)
    except OSError:
        pass
    return indexed


_SDLXLIFF_SIDECAR_MANIFEST_VERSION = 1
_SDLXLIFF_SIDECAR_MANIFEST_TYPE = _SIDECAR_FRESHNESS_MANIFEST_TYPE
_SDLXLIFF_SIDECAR_MANIFEST_LOCK = _SIDECAR_FRESHNESS_MANIFEST_LOCK


def _sdlxliff_sidecar_manifest_path(output_dir):
    return os.path.join(
        str(output_dir or ""),
        "SDLXLIFF",
        "sdlxliff_manifest.json",
    )


def _read_sdlxliff_sidecar_manifest(output_dir):
    """Read the optional sidecar freshness manifest.

    ``None`` deliberately means "use the legacy mtime check".  This applies
    to missing and unreadable manifests so older workspaces remain usable.
    """
    manifest_path = _sdlxliff_sidecar_manifest_path(output_dir)
    if not os.path.isfile(manifest_path):
        return None
    try:
        with _SDLXLIFF_SIDECAR_MANIFEST_LOCK:
            with open(manifest_path, "r", encoding="utf-8") as source:
                manifest = json.load(source)
        if not isinstance(manifest, dict):
            return None
        if manifest.get("type") != _SDLXLIFF_SIDECAR_MANIFEST_TYPE:
            return None
        if not isinstance(manifest.get("entries"), dict):
            return None
        return manifest
    except Exception:
        return None


def _update_sdlxliff_sidecar_manifest(output_dir, entry_updates):
    """Merge successful sidecar hash records and replace the manifest atomically."""
    updates = {
        str(key): value
        for key, value in (entry_updates or {}).items()
        if key and isinstance(value, dict)
    }
    if not updates:
        return False
    manifest_path = _sdlxliff_sidecar_manifest_path(output_dir)
    try:
        with _SDLXLIFF_SIDECAR_MANIFEST_LOCK:
            current = _read_sdlxliff_sidecar_manifest(output_dir)
            if current is None:
                current = {
                    "version": _SDLXLIFF_SIDECAR_MANIFEST_VERSION,
                    "type": _SDLXLIFF_SIDECAR_MANIFEST_TYPE,
                    "hash_algorithm": "sha256",
                    "entries": {},
                }
            entries = current.setdefault("entries", {})
            entries.update(updates)
            current["version"] = _SDLXLIFF_SIDECAR_MANIFEST_VERSION
            current["type"] = _SDLXLIFF_SIDECAR_MANIFEST_TYPE
            current["hash_algorithm"] = "sha256"
            _write_progress_snapshot_atomic(manifest_path, current)
        return True
    except Exception:
        return False


def _sdlxliff_sha256_bytes(payload):
    return hashlib.sha256(payload).hexdigest()


def _sdlxliff_sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as source:
        while True:
            block = source.read(1024 * 1024)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()


def _sdlxliff_file_stat_record(path):
    stat = os.stat(path)
    return {
        "size": int(stat.st_size),
        "mtime_ns": int(getattr(
            stat,
            "st_mtime_ns",
            int(stat.st_mtime * 1000000000),
        )),
    }


def _sdlxliff_source_record(source_path):
    """Describe the loose file or EPUB member used as the sidecar source."""
    location = str(source_path or "")
    if not location:
        return None
    container_path = ""
    member = ""
    if "!" in location:
        possible_container, possible_member = location.rsplit("!", 1)
        if os.path.isfile(possible_container):
            container_path = os.path.abspath(possible_container)
            member = possible_member
    if container_path:
        record = {
            "kind": "epub_member",
            "container": container_path,
            "member": member,
        }
        try:
            record.update(_sdlxliff_file_stat_record(container_path))
        except OSError:
            pass
        return record
    if os.path.isfile(location):
        file_path = os.path.abspath(location)
        record = {"kind": "file", "path": file_path}
        try:
            record.update(_sdlxliff_file_stat_record(file_path))
        except OSError:
            pass
        return record
    return {"kind": "unresolved", "location": location}


def _sdlxliff_decode_html_bytes(payload):
    for encoding in ("utf-8", "utf-8-sig", "cp949", "latin-1"):
        try:
            return payload.decode(encoding)
        except Exception:
            continue
    return payload.decode("utf-8", errors="replace")


def _sdlxliff_source_record_payload(source_record):
    if not isinstance(source_record, dict):
        return None
    kind = source_record.get("kind")
    try:
        if kind == "file":
            source_path = source_record.get("path")
            if not source_path or not os.path.isfile(source_path):
                return None
            with open(source_path, "rb") as source:
                return _sdlxliff_decode_html_bytes(source.read())
        if kind == "epub_member":
            container = source_record.get("container")
            member = source_record.get("member")
            if not container or not member or not os.path.isfile(container):
                return None
            with zipfile.ZipFile(container, "r") as source_zip:
                return _sdlxliff_decode_html_bytes(source_zip.read(member))
    except Exception:
        return None
    return None


def _sdlxliff_manifest_freshness_record(
    output_name,
    sidecar_path,
    output_path,
    source_html,
    source_path,
):
    output_stat = _sdlxliff_file_stat_record(output_path)
    source_record = _sdlxliff_source_record(source_path)
    return {
        "output_name": os.path.basename(str(output_name or "").replace("\\", "/")),
        "sidecar_name": os.path.basename(str(sidecar_path or "").replace("\\", "/")),
        "output_sha256": _sdlxliff_sha256_file(output_path),
        "output_size": output_stat["size"],
        "output_mtime_ns": output_stat["mtime_ns"],
        "source_sha256": _sdlxliff_sha256_bytes(str(source_html or "").encode("utf-8")),
        "source": source_record,
    }


def _sdlxliff_manifest_record_current(
    record,
    output_path,
    output_stat=None,
    source_stat_cache=None,
):
    """Return ``(is_current, refreshed_record)`` for a usable hash record."""
    if not isinstance(record, dict):
        return None, None
    expected_output_hash = str(record.get("output_sha256") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{64}", expected_output_hash):
        return None, None
    if not isinstance(output_stat, dict):
        try:
            output_stat = _sdlxliff_file_stat_record(output_path)
        except OSError:
            return False, None

    try:
        recorded_output_size = int(record["output_size"])
        recorded_output_mtime = int(record["output_mtime_ns"])
    except (KeyError, TypeError, ValueError):
        return None, None
    refreshed = None
    output_signature_matches = (
        recorded_output_size == output_stat["size"]
        and recorded_output_mtime == output_stat["mtime_ns"]
    )
    if not output_signature_matches:
        try:
            if _sdlxliff_sha256_file(output_path) != expected_output_hash:
                return False, None
        except OSError:
            return False, None
        refreshed = dict(record)
        refreshed["output_size"] = output_stat["size"]
        refreshed["output_mtime_ns"] = output_stat["mtime_ns"]

    expected_source_hash = str(record.get("source_sha256") or "").lower()
    source_record = record.get("source")
    if re.fullmatch(r"[0-9a-f]{64}", expected_source_hash) and isinstance(source_record, dict):
        source_kind = source_record.get("kind")
        tracked_path = (
            source_record.get("path")
            if source_kind == "file"
            else source_record.get("container") if source_kind == "epub_member" else None
        )
        # A moved or temporarily unavailable source must not invalidate a
        # perfectly usable existing sidecar.  If it is available, however,
        # verify any changed source signature by content.
        if tracked_path:
            try:
                if isinstance(source_stat_cache, dict):
                    source_cache_key = os.path.normcase(
                        os.path.abspath(tracked_path)
                    )
                    if source_cache_key not in source_stat_cache:
                        try:
                            source_stat_cache[source_cache_key] = (
                                _sdlxliff_file_stat_record(tracked_path)
                            )
                        except OSError:
                            source_stat_cache[source_cache_key] = None
                    source_stat = source_stat_cache.get(source_cache_key)
                    if not isinstance(source_stat, dict):
                        return True, refreshed
                else:
                    source_stat = _sdlxliff_file_stat_record(tracked_path)
                recorded_source_size = int(source_record["size"])
                recorded_source_mtime = int(source_record["mtime_ns"])
                source_signature_matches = (
                    recorded_source_size == source_stat["size"]
                    and recorded_source_mtime == source_stat["mtime_ns"]
                )
                if not source_signature_matches:
                    source_payload = _sdlxliff_source_record_payload(source_record)
                    if source_payload is None:
                        return False, None
                    current_source_hash = _sdlxliff_sha256_bytes(source_payload.encode("utf-8"))
                    if current_source_hash != expected_source_hash:
                        return False, None
                    refreshed = dict(refreshed or record)
                    refreshed_source = dict(source_record)
                    refreshed_source.update(source_stat)
                    refreshed["source"] = refreshed_source
            except (KeyError, OSError, TypeError, ValueError):
                pass

    return True, refreshed


_PROGRESS_READER_HTML_EXTENSIONS = (".html", ".htm", ".xhtml")


def _manual_editing_output_filename(entry, current_output, retain_source_extension):
    """Return the HTML filename a manual sidecar must save for this naming mode."""
    entry = entry if isinstance(entry, dict) else {}
    source_name = ""
    for key in (
        "original_name", "original_basename", "original_filename",
        "filename", "href",
    ):
        candidate = os.path.basename(
            str(entry.get(key) or "").replace("\\", "/")
        )
        if candidate and candidate.lower().endswith(_PROGRESS_READER_HTML_EXTENSIONS):
            source_name = candidate
            break

    current_name = os.path.basename(
        str(current_output or entry.get("output_file") or "").replace("\\", "/")
    )
    if not source_name:
        source_name = current_name
    if source_name.lower().startswith("response_"):
        source_name = source_name[len("response_"):]
    if not source_name:
        return current_name

    if retain_source_extension:
        return source_name

    source_stem, _source_ext = os.path.splitext(source_name)
    return f"response_{source_stem or source_name}.html"


def _progress_item_is_html(display_info) -> bool:
    """Return whether a Progress Manager row points to an HTML document."""
    display_info = display_info if isinstance(display_info, dict) else {}
    progress_entry = display_info.get("info", {}) or {}
    output_file = (
        display_info.get("output_file")
        or progress_entry.get("output_file")
        or ""
    )
    return str(output_file).lower().endswith(_PROGRESS_READER_HTML_EXTENSIONS)


def _index_epub_html_members(member_names):
    """Build the reusable lookup used to match progress rows to EPUB members."""
    html_members = [
        str(name).replace("\\", "/")
        for name in (member_names or [])
        if str(name).lower().endswith(_PROGRESS_READER_HTML_EXTENSIONS)
    ]
    by_path = {}
    by_basename = {}
    by_stem = {}
    for member in html_members:
        normalized = member.lower().strip("/")
        basename = os.path.basename(normalized)
        stem = _normalize_progress_match_name(basename).lower()
        by_path.setdefault(normalized, member)
        by_basename.setdefault(basename, member)
        if stem:
            by_stem.setdefault(stem, member)
    return by_path, by_basename, by_stem


def _match_epub_html_member_basename(
    member_names,
    candidates,
    member_index=None,
):
    """Match progress filenames to an EPUB HTML member and return its basename.

    ``member_index`` lets callers matching many rows reuse the same lookup.
    Building it for every chapter made the Progress Manager launch path scale
    quadratically with the EPUB chapter count.
    """
    if member_index is None:
        member_index = _index_epub_html_members(member_names)
    by_path, by_basename, by_stem = member_index

    candidate_values = [str(value).replace("\\", "/") for value in (candidates or []) if value]
    for candidate in candidate_values:
        normalized = candidate.lower().strip("/")
        basename = os.path.basename(normalized)
        match = by_path.get(normalized) or by_basename.get(basename)
        if match:
            return os.path.basename(match)
    for candidate in candidate_values:
        stem = _normalize_progress_match_name(candidate).lower()
        match = by_stem.get(stem)
        if match:
            return os.path.basename(match)
    return None


def _glossary_progress_filename_keys(name):
    """Return filename keys shared by glossary progress/index matching."""
    base = os.path.basename(str(name or ""))
    if not base:
        return set()
    stem = os.path.splitext(base)[0]
    keys = {base.lower(), stem.lower()}
    if stem.lower().startswith('response_'):
        keys.add(stem[9:].lower())
    return {key for key in keys if key}


def _filter_glossary_source_chapter_map(
    chapter_map, spine_index_map, source_filenames
):
    """Restrict a raw EPUB chapter map to the mapped parallel-source files."""

    requested = [str(name or "") for name in (source_filenames or []) if name]
    if not requested:
        return dict(chapter_map or {}), dict(spine_index_map or {})

    chapter_map = dict(chapter_map or {})
    spine_index_map = dict(spine_index_map or {})
    key_to_indices = {}
    for source_index, filename in sorted(chapter_map.items()):
        for key in _glossary_progress_filename_keys(filename):
            key_to_indices.setdefault(key, []).append(source_index)

    used_indices = set()
    filtered_map = {}
    filtered_spine_map = {}
    for mapped_index, requested_filename in enumerate(requested):
        source_index = None
        for key in _glossary_progress_filename_keys(requested_filename):
            source_index = next(
                (
                    index
                    for index in key_to_indices.get(key, [])
                    if index not in used_indices
                ),
                None,
            )
            if source_index is not None:
                break
        if source_index is None:
            filtered_map[mapped_index] = os.path.basename(requested_filename)
            filtered_spine_map[mapped_index] = mapped_index + 1
            continue
        used_indices.add(source_index)
        filtered_map[mapped_index] = chapter_map[source_index]
        filtered_spine_map[mapped_index] = spine_index_map.get(
            source_index, source_index + 1
        )

    return filtered_map, filtered_spine_map


def _parallel_glossary_progress_filename_aliases(source_filenames):
    """Map generated pair_NNNN chapter names onto displayed raw rows."""

    aliases = {}
    for mapped_index, source_filename in enumerate(source_filenames or []):
        if not source_filename:
            continue
        generated_filename = f"pair_{mapped_index + 1:04d}.xhtml"
        for key in _glossary_progress_filename_keys(generated_filename):
            aliases[key] = mapped_index
    return aliases


def _map_zero_based_glossary_progress_index(value, progress_data, filename_key_to_index):
    """Map an extraction-list index onto the full OPF progress-manager view."""
    try:
        index = int(value)
    except (TypeError, ValueError):
        return None
    progress_data = progress_data if isinstance(progress_data, dict) else {}
    chapter_filenames = progress_data.get('chapter_filenames', {})
    progress_filename = None
    if isinstance(chapter_filenames, dict):
        progress_filename = chapter_filenames.get(str(index))
        if progress_filename is None:
            progress_filename = chapter_filenames.get(index)
    if progress_filename:
        for filename_key in _glossary_progress_filename_keys(progress_filename):
            if filename_key in filename_key_to_index:
                return filename_key_to_index[filename_key]
        return None
    return index


def _snapshot_progress_output_dir(output_dir):
    """Return one reusable directory snapshot for large EPUB matching.

    The old loader repeatedly called ``listdir``/``isfile`` for every spine
    entry.  Keeping names, normalized-name matches, and mtimes together makes
    the initial scan linear in the number of files.
    """
    filenames = set()
    normalized = {}
    mtimes = {}
    try:
        with os.scandir(output_dir) as scan:
            for entry in scan:
                try:
                    if not entry.is_file():
                        continue
                except OSError:
                    continue
                filenames.add(entry.name)
                normalized.setdefault(_normalize_progress_match_name(entry.name), entry.name)
                try:
                    mtimes[entry.name] = entry.stat().st_mtime
                except OSError:
                    pass
    except OSError:
        pass
    return filenames, normalized, mtimes


def _write_progress_snapshot_atomic(path, payload):
    """Atomically persist a Progress Manager snapshot.

    Windows can briefly deny replacement while the translator, a file
    watcher, or antivirus software has the destination open.  The main
    translation progress writer already tolerates that sharing window; the
    Progress Manager must do the same because its HTML edits happen before
    this commit.
    """
    progress_dir = os.path.dirname(os.path.abspath(path))
    os.makedirs(progress_dir, exist_ok=True)
    temp_path = (
        f"{path}.{os.getpid()}.{threading.get_ident()}."
        f"{time.time_ns()}.tmp"
    )
    try:
        with open(temp_path, "w", encoding="utf-8") as target:
            json.dump(payload, target, ensure_ascii=False, indent=2)
            target.flush()
            try:
                os.fsync(target.fileno())
            except OSError:
                pass
        last_error = None
        for attempt in range(20):
            try:
                os.replace(temp_path, path)
                return
            except OSError as exc:
                last_error = exc
                winerror = getattr(exc, "winerror", None)
                retryable = winerror in {5, 32} or (
                    os.name == "nt" and isinstance(exc, PermissionError)
                )
                if not retryable or attempt >= 19:
                    raise
                # Keep this bounded while covering the transient sharing
                # locks commonly produced by Windows scanners/watchers.
                time.sleep(min(0.4, 0.03 * (2 ** min(attempt, 4))))
        if last_error is not None:  # pragma: no cover - loop always returns/raises
            raise last_error
    finally:
        if os.path.exists(temp_path):
            try:
                os.remove(temp_path)
            except OSError:
                pass


_RETRANSLATION_PROGRESS_LOCKS_GUARD = threading.Lock()
_RETRANSLATION_PROGRESS_LOCKS = {}


def _retranslation_progress_lock(path):
    """Return one in-process lock for a Progress Manager JSON file."""
    key = os.path.normcase(os.path.abspath(os.fspath(path)))
    with _RETRANSLATION_PROGRESS_LOCKS_GUARD:
        lock = _RETRANSLATION_PROGRESS_LOCKS.get(key)
        if lock is None:
            lock = threading.RLock()
            _RETRANSLATION_PROGRESS_LOCKS[key] = lock
        return lock


def _merge_retranslation_progress_changes(baseline, changed, latest):
    """Apply only this retranslation action's JSON changes to ``latest``.

    Progress Manager windows can start from different snapshots.  A normal
    full-file write would let the last window overwrite changes made by the
    others.  This recursive three-way merge preserves fields that this action
    did not change while applying its selected chapter resets.
    """
    if baseline == changed:
        return copy.deepcopy(latest)
    if isinstance(baseline, dict) and isinstance(changed, dict):
        merged = copy.deepcopy(latest) if isinstance(latest, dict) else {}
        ordered_keys = list(baseline)
        ordered_keys.extend(key for key in changed if key not in baseline)
        for key in ordered_keys:
            in_baseline = key in baseline
            in_changed = key in changed
            in_latest = isinstance(latest, dict) and key in latest
            if in_baseline and not in_changed:
                # Do not remove a value another action changed after our
                # snapshot; this matters for merged-child chapter entries.
                if not in_latest or latest.get(key) == baseline.get(key):
                    merged.pop(key, None)
                continue
            if not in_baseline:
                merged[key] = copy.deepcopy(changed[key])
                continue
            if not in_latest:
                merged[key] = copy.deepcopy(changed[key])
                continue
            merged[key] = _merge_retranslation_progress_changes(
                baseline[key],
                changed[key],
                latest[key],
            )
        return merged
    return copy.deepcopy(changed)


def _merge_and_write_retranslation_progress(
    path,
    baseline,
    changed,
    *,
    authoritative_chunk_resets=None,
):
    """Merge one selection reset into the newest progress file atomically."""
    with _retranslation_progress_lock(path):
        latest = copy.deepcopy(baseline)
        if os.path.isfile(path):
            with open(path, "r", encoding="utf-8") as progress_file:
                disk_progress = json.load(progress_file)
            if isinstance(disk_progress, dict):
                latest = disk_progress
        merged = _merge_retranslation_progress_changes(
            baseline,
            changed,
            latest,
        )
        # Explicit Retranslate Selected chunk resets are authoritative. A
        # translator save racing this dialog must not resurrect the selected
        # result/metadata after the HTML segment has already been removed.
        for reset_spec in authoritative_chunk_resets or []:
            if not isinstance(reset_spec, dict):
                continue
            chunk_key = str(reset_spec.get("chunk_key") or "")
            parent_key = reset_spec.get("parent_key")
            indices = reset_spec.get("indices") or []
            chunk_entry = merged.get("chapter_chunks", {}).get(chunk_key)
            if not isinstance(chunk_entry, dict):
                continue
            reset_chunks_for_retranslation(chunk_entry, indices)
            parent_entry = merged.get("chapters", {}).get(parent_key)
            if isinstance(parent_entry, dict):
                parent_entry["status"] = "pending"
                parent_entry["failure_reason"] = ""
                parent_entry["error_message"] = ""
                parent_entry["last_updated"] = time.time()
                _clear_refinement_progress_fields(parent_entry)
                _sync_parent_chunk_qa_summary(
                    merged,
                    parent_key,
                    chunk_key,
                )
        _write_progress_snapshot_atomic(path, merged)
        return merged


def _bulk_retranslation_sidecar_updates(
    paths,
    *,
    manual_editing,
    max_workers,
):
    """Reset or delete independent SDLXLIFF sidecars in parallel."""
    unique_paths = []
    seen = set()
    for path in paths or []:
        if not path:
            continue
        normalized = os.path.normcase(os.path.abspath(os.fspath(path)))
        if normalized in seen:
            continue
        seen.add(normalized)
        unique_paths.append(os.fspath(path))

    result = {
        "cleared": 0,
        "deleted": 0,
        "failed": [],
    }
    if not unique_paths:
        return result

    try:
        worker_count = min(
            len(unique_paths),
            max(1, int(max_workers or 1)),
        )
    except (TypeError, ValueError):
        worker_count = 1

    def _update_one(path):
        try:
            if manual_editing:
                changed = _reset_sdlxliff_target_for_manual_retranslation(path)
                return "cleared" if changed else "missing", path, None
            try:
                os.remove(path)
            except FileNotFoundError:
                return "missing", path, None
            return "deleted", path, None
        except Exception as exc:
            return "failed", path, str(exc)

    if worker_count == 1:
        outcomes = map(_update_one, unique_paths)
        for status, path, error in outcomes:
            if status in {"cleared", "deleted"}:
                result[status] += 1
            elif status == "failed":
                result["failed"].append((path, error))
        return result

    with ThreadPoolExecutor(
        max_workers=worker_count,
        thread_name_prefix="RetranslationSidecar",
    ) as executor:
        for status, path, error in executor.map(_update_one, unique_paths):
            if status in {"cleared", "deleted"}:
                result[status] += 1
            elif status == "failed":
                result["failed"].append((path, error))
    return result


def _persist_progress_manager_source_link(file_path, output_dir):
    """Persist the raw input used by a Progress Manager workspace.

    Progress Manager can scaffold an output folder before translation starts.
    The Library scans that folder independently, so it needs the same durable
    source association that a real translation run writes.  Keep both lookup
    routes in sync:

      * ``source_epub.txt`` ties this exact workspace to its input.
      * The Library raw-input registry provides a fallback if the sidecar is
        later removed or the workspace is relocated.

    Returns True when the workspace has a valid sidecar after this call.
    Registry failures are intentionally non-fatal: the exact workspace
    sidecar is sufficient for the Library to recover the EPUB spine.
    """
    if not file_path or not output_dir:
        return False
    try:
        source_path = os.path.abspath(str(file_path))
        workspace = os.path.abspath(str(output_dir))
    except (TypeError, ValueError, OSError):
        return False
    if not os.path.isfile(source_path) or not os.path.isdir(workspace):
        return False

    sidecar = os.path.join(workspace, "source_epub.txt")
    linked = False
    try:
        current = ""
        if os.path.isfile(sidecar):
            with open(sidecar, "r", encoding="utf-8", errors="ignore") as f:
                current = f.read().strip()
        if current:
            current_path = (
                current
                if os.path.isabs(current)
                else os.path.join(workspace, current)
            )
            try:
                linked = (
                    os.path.normcase(os.path.abspath(current_path))
                    == os.path.normcase(source_path)
                )
            except (TypeError, ValueError, OSError):
                linked = False
        if not linked:
            temp_path = (
                f"{sidecar}.{os.getpid()}.{threading.get_ident()}."
                f"{time.time_ns()}.tmp"
            )
            try:
                with open(temp_path, "w", encoding="utf-8") as target:
                    target.write(source_path)
                os.replace(temp_path, sidecar)
                linked = True
            finally:
                if os.path.exists(temp_path):
                    try:
                        os.remove(temp_path)
                    except OSError:
                        pass
    except OSError:
        linked = False

    try:
        from epub_library import record_library_raw_input
        record_library_raw_input(source_path)
    except Exception:
        # Progress Manager must still open if the optional Library registry
        # cannot be loaded or written.  The sidecar remains authoritative.
        pass
    return linked


def _progress_path_signature(path):
    """Cheap signature used to avoid parsing unchanged progress files."""
    try:
        stat = os.stat(path)
        return stat.st_mtime_ns, stat.st_size
    except OSError:
        return None


def _clear_refinement_progress_fields(entry):
    """Remove refinement state from an entry and its restorable snapshot."""
    if not isinstance(entry, dict):
        return 0
    removed = 0
    fields = (
        "refinement_status",
        "refined_at",
        "refinement_error",
        "unrefined_backup_file",
    )
    for field in fields:
        if field in entry:
            entry.pop(field, None)
            removed += 1
    previous_entry = entry.get("previous_progress_entry")
    if isinstance(previous_entry, dict):
        for field in fields:
            if field in previous_entry:
                previous_entry.pop(field, None)
                removed += 1
    return removed


def _progress_entry_refined_for_display(entry):
    current = entry if isinstance(entry, dict) else None
    seen = set()
    while isinstance(current, dict) and id(current) not in seen:
        seen.add(id(current))
        status = str(current.get('refinement_status') or '').lower().strip()
        if status:
            return status in ('refined', 'completed')
        current = current.get('previous_progress_entry')
    return False


def _progress_entry_refinement_failed_for_display(entry):
    current = entry if isinstance(entry, dict) else None
    seen = set()
    while isinstance(current, dict) and id(current) not in seen:
        seen.add(id(current))
        status = str(current.get('refinement_status') or '').lower().strip()
        if status:
            return status in ('failed', 'error')
        current = current.get('previous_progress_entry')
    return False


def _combine_glossary_progress_legend_stats(
    chapter_stats,
    refinement_status_counts,
):
    """Combine chapter and refinement rows into the displayed legend totals."""
    chapter_stats = chapter_stats if isinstance(chapter_stats, dict) else {}
    refinement_status_counts = (
        refinement_status_counts
        if isinstance(refinement_status_counts, dict)
        else {}
    )

    def _count(mapping, key):
        try:
            return max(0, int(mapping.get(key, 0) or 0))
        except (TypeError, ValueError):
            return 0

    normalized_refinement = {}
    for raw_status, raw_count in refinement_status_counts.items():
        status = str(raw_status or 'unknown').strip().lower().replace(' ', '_')
        try:
            count = max(0, int(raw_count or 0))
        except (TypeError, ValueError):
            count = 0
        normalized_refinement[status] = (
            normalized_refinement.get(status, 0) + count
        )

    result = {
        key: _count(chapter_stats, key)
        for key in (
            'total',
            'completed',
            'skipped',
            'in_progress',
            'failed',
            'merged',
            'remaining',
        )
    }
    result['total'] += sum(normalized_refinement.values())
    result['completed'] += (
        normalized_refinement.get('completed', 0)
        + normalized_refinement.get('refined', 0)
    )
    result['skipped'] += normalized_refinement.get('skipped', 0)
    result['in_progress'] += (
        normalized_refinement.get('in_progress', 0)
        + normalized_refinement.get('partially_in_progress', 0)
    )
    result['not_refined'] = normalized_refinement.get('not_refined', 0)
    result['refine_failed'] = (
        normalized_refinement.get('refine_failed', 0)
        + normalized_refinement.get('failed', 0)
        + normalized_refinement.get('error', 0)
    )
    return result


def _glossary_refinement_type_key(value):
    key = str(value or '').strip().casefold()
    return 'terms' if key in ('term', 'terms') else key


def _normalize_glossary_refinement_selection(refinement_keys, active_types):
    """Resolve selected row keys, with the aggregate row taking precedence."""
    keys = [str(key or '') for key in refinement_keys or [] if str(key or '')]
    active = [str(entry_type or '').strip() for entry_type in active_types or [] if str(entry_type or '').strip()]
    if any(key.startswith('all::') for key in keys):
        return active
    requested = {
        _glossary_refinement_type_key(key.split('::', 1)[1])
        for key in keys
        if key.startswith('type::') and '::' in key
    }
    return [
        entry_type for entry_type in active
        if _glossary_refinement_type_key(entry_type) in requested
    ]


def _resolve_dialog_window_parent(parent):
    """Return the top-level window that owns a dialog-triggering child widget."""
    if parent is None:
        return None
    try:
        owner = parent.window()
        if owner is not None:
            return owner
    except (AttributeError, RuntimeError):
        pass
    return parent


def _derive_glossary_refinement_aggregate_status(statuses, represented=None):
    normalized = [str(status or 'not_refined').strip().lower() for status in statuses or []]
    if any(status in ('failed', 'error', 'refine_failed') for status in normalized):
        return 'failed'
    if any(status == 'in_progress' for status in normalized):
        actionable_statuses = [status for status in normalized if status != 'skipped']
        if actionable_statuses and all(status == 'in_progress' for status in actionable_statuses):
            return 'in_progress'
        return 'partially_in_progress'
    if any(status in ('not_refined', 'unknown', '') for status in normalized):
        return 'not_refined'
    if normalized and all(status == 'skipped' for status in normalized):
        return 'skipped'
    if represented is not None and any(not bool(value) for value in represented):
        # A newly enabled type has joined the aggregate scope but has not yet
        # acquired its own persisted refinement result.
        return 'not_refined'
    return 'completed'


def _progress_entry_model_for_display(entry):
    if _progress_entry_is_completed_image_only_for_display(entry):
        return 'COPIED'

    current = entry if isinstance(entry, dict) else None
    seen = set()
    while isinstance(current, dict) and id(current) not in seen:
        seen.add(id(current))
        model_name = str(
            current.get('model_name') or current.get('model') or ''
        ).strip()
        if model_name:
            return model_name
        current = current.get('previous_progress_entry')
    return ''


def _progress_status_hides_model_for_display(status):
    """Return whether a row has not started and therefore has no current model."""
    normalized = str(status or '').strip().lower().replace(' ', '_')
    return normalized in {'pending', 'not_translated', 'not_completed'}


def _progress_entry_is_completed_image_only_for_display(entry):
    """Return whether the row's current result is an image-only copy."""
    if not isinstance(entry, dict):
        return False

    # Progress Manager rows wrap the current persisted entry in either ``info``
    # or ``progress_entry``. Do not walk ``previous_progress_entry`` here: a
    # new translation in progress must not inherit the old image-only badge.
    candidates = [entry]
    for key in ('info', 'progress_entry'):
        candidate = entry.get(key)
        if isinstance(candidate, dict):
            candidates.append(candidate)
    return any(
        str(candidate.get('status') or '').lower().strip()
        == 'completed_image_only'
        for candidate in candidates
    )


def _format_qa_issue_for_progress_display(issue, qa_issue_previews=None):
    """Render a QA issue with its saved preview context."""
    issue_code = str(issue)
    previews = qa_issue_previews if isinstance(qa_issue_previews, dict) else {}
    preview = re.sub(
        r'\s+',
        ' ',
        str(previews.get(issue_code, '') or ''),
    ).strip()
    preview_limit = 420 if issue_code.startswith('ai_truncation_detected') else 160
    if len(preview) > preview_limit:
        preview = preview[:preview_limit - 3].rstrip() + '...'
    return (
        f'{issue_code} — Preview: {preview}'
        if preview
        else issue_code
    )


def _select_progress_entry_for_display(entries, display_status=None):
    """Pick the single progress entry that should drive a visible row."""
    candidates = [entry for entry in (entries or []) if isinstance(entry, dict)]
    if not candidates:
        return {}

    desired = str(display_status or '').lower().strip()
    completed_statuses = (
        'completed',
        'completed_empty',
        'completed_image_only',
    )

    def _score(entry):
        status = str(entry.get('status') or '').lower().strip()
        score = 0
        if desired == 'in_progress':
            if status == 'in_progress':
                score += 100
            elif status in completed_statuses:
                score += 20
        elif desired == 'completed':
            if status in completed_statuses:
                score += 100
            if _progress_entry_refined_for_display(entry):
                score += 50
        elif desired in ('failed', 'qa_failed'):
            if status == desired:
                score += 100
            elif status in ('failed', 'qa_failed', 'error'):
                score += 80
        elif desired == 'merged' and status == 'merged':
            score += 100
        elif desired and status == desired:
            score += 100

        if str(entry.get('model_name') or entry.get('model') or '').strip():
            score += 10
        elif _progress_entry_model_for_display(entry):
            score += 3

        try:
            score += min(float(entry.get('last_updated') or 0), 9999999999) / 9999999999
        except Exception:
            pass
        return score

    return max(candidates, key=_score)


class _GlossaryProgressAsyncBridge(QObject):
    progress = Signal(object)
    finished = Signal(object)
    failed = Signal(str)

    def __init__(self, on_finished=None, on_failed=None, on_progress=None, parent=None):
        super().__init__(parent)
        self._on_finished = on_finished
        self._on_failed = on_failed
        self._on_progress = on_progress
        self.progress.connect(self._handle_progress)
        self.finished.connect(self._handle_finished)
        self.failed.connect(self._handle_failed)

    @Slot(object)
    def _handle_progress(self, payload):
        if callable(self._on_progress):
            self._on_progress(payload)

    @Slot(object)
    def _handle_finished(self, payload):
        if callable(self._on_finished):
            self._on_finished(payload)

    @Slot(str)
    def _handle_failed(self, message):
        if callable(self._on_failed):
            self._on_failed(message)


def _sdlxliff_machine_translation_output_name(path_or_name):
    name = os.path.basename(str(path_or_name or "").replace("\\", "/"))
    suffix = ".sdlxliff"
    if name.lower().endswith(suffix):
        name = name[:-len(suffix)]
    return name


def _sdlxliff_machine_translation_path(output_dir, output_or_sidecar):
    output_name = _sdlxliff_machine_translation_output_name(output_or_sidecar)
    if not output_name:
        return None
    base_dir = str(output_dir or "")
    if not base_dir:
        sidecar_path = str(output_or_sidecar or "")
        sidecar_dir = os.path.dirname(sidecar_path)
        if os.path.basename(sidecar_dir).lower() == "sdlxliff":
            base_dir = os.path.dirname(sidecar_dir)
    if not base_dir:
        return None
    safe_name = re.sub(r'[^A-Za-z0-9._ -]+', '_', output_name).strip(" .")
    if not safe_name:
        safe_name = hashlib.sha256(output_name.encode("utf-8", errors="replace")).hexdigest()
    return os.path.join(base_dir, "SDLXLIFF", _MACHINE_TRANSLATION_DIR, f"{safe_name}.json")

def _get_app_dir() -> str:
    """Return the application's base directory (Windows-safe)."""
    if platform.system() == 'Windows':
        if getattr(sys, 'frozen', False):
            return os.path.dirname(sys.executable)
        return os.path.dirname(os.path.abspath(__file__))
    return os.getcwd()


# WindowManager and UIHelper removed - not needed in PySide6
# Qt handles window management and UI utilities automatically


class AnimatedRefreshButton(QPushButton):
    """Custom QPushButton with rotation animation for refresh action using Halgakos.ico"""
    
    def __init__(self, text="Refresh", parent=None):
        super().__init__(text, parent)
        self._rotation = 0
        self._animation = None
        self._original_text = text
        self._timer = None
        self._animation_step = 0
        self._original_icon = None
        
        # Try to load Halgakos.ico
        try:
            # Get base directory
            base_dir = getattr(sys, '_MEIPASS', os.path.dirname(os.path.abspath(__file__)))
            ico_path = os.path.join(base_dir, 'Halgakos.ico')
            if os.path.isfile(ico_path):
                self._original_icon = QIcon(ico_path)
                self.setIcon(self._original_icon)
                self.setIconSize(self.iconSize() * 1.2)  # Make icon slightly larger
        except Exception as e:
            print(f"Could not load Halgakos.ico for refresh button: {e}")
        
    def get_rotation(self):
        return self._rotation
    
    def set_rotation(self, angle):
        self._rotation = angle
        self.update()  # Trigger repaint
    
    # Define rotation as a Qt Property for animation
    rotation = Property(float, get_rotation, set_rotation)
    
    def start_animation(self):
        """Start the spinning animation"""
        if self._timer and self._timer.isActive():
            return  # Already animating
        
        self.setProperty("refreshActive", True)
        self.style().unpolish(self)
        self.style().polish(self)
        
        # Start timer-based animation for icon rotation
        self._animation_step = 0
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._update_animation_frame)
        self._timer.start(50)  # Update every 50ms for smooth rotation
    
    def _update_animation_frame(self):
        """Update animation frame by rotating the icon"""
        if self._original_icon:
            # Increment rotation angle (30 degrees per frame for smooth spinning)
            self._rotation = (self._rotation + 30) % 360
            
            # Create a rotated version of the icon
            pixmap = self._original_icon.pixmap(self.iconSize())
            transform = QTransform().rotate(self._rotation)
            rotated_pixmap = pixmap.transformed(transform, Qt.SmoothTransformation)
            
            # Set the rotated icon
            self.setIcon(QIcon(rotated_pixmap))
    
    def stop_animation(self):
        """Stop the spinning animation"""
        if self._timer:
            self._timer.stop()
            self._timer = None
            self._rotation = 0
            self._animation_step = 0
            
            # Restore original icon (unrotated)
            if self._original_icon:
                self.setIcon(self._original_icon)
            
            self.setProperty("refreshActive", False)
            self.style().unpolish(self)
            self.style().polish(self)
            
            self.update()


